using Microsoft.Data.SqlClient;

var connectionString = "Server=tcp:sqlserver-demo.database.windows.net,1433;Database=AppDb;User ID=sqladmin;Password=<SecurePassword>;Encrypt=True;TrustServerCertificate=False;Connection Timeout=30;";

using var conn = new SqlConnection(connectionString);
await conn.OpenAsync();

using var cmd = new SqlCommand("SELECT GETDATE()", conn);
var result = await cmd.ExecuteScalarAsync();
Console.WriteLine($"Server time: {result}");
